#!/usr/bin/env node
// Generates the client's music data from shared/music/*.json (docs/AUDIO.md §2a). The output is
// checked in; CI regenerates it and fails on any diff (a changed audio file changes its hash).
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { loadMusic, MUSIC_DIR } from "./load.mjs";

const root = join(MUSIC_DIR, "..", "..");
const data = loadMusic();
const ts = [
  "// Generated by shared/music/gen.mjs from shared/music/*.json. Do not edit.",
  "import type { MusicData } from './musicTypes';",
  "",
  `export const MUSIC_DATA: MusicData = ${JSON.stringify(data, null, 2)};`,
  "",
];
writeFileSync(join(root, "client/src/audio/music.gen.ts"), ts.join("\n"));
console.log(`music: ${data.tracks.length} tracks`);
